base:
/* Selectors are plain elements: the frontend classes are build hashes. The
   first/last cell rules are restated because the frontend zeroes the outer
   padding at a higher specificity. */
body[data-ds-dark-theme] table {
    font-variant-numeric: tabular-nums;
}

/* A table's max-width is ignored while it is display: table, so the column box
   is what keeps it inside the text column. Keyed on the wrapper itself: the
   frontend only tags wide tables with md-table-wide, so that class alone let
   short tables keep their own width. */
body[data-ds-dark-theme] :has(> table),
body[data-ds-dark-theme] .md-table-wide {
    max-width: 100%;
    max-height: none;
    overflow-x: auto;
    overflow-y: visible;
}

body[data-ds-dark-theme] table :is(th, td) {
    padding: 5px 12px;
    max-width: none;
}

body[data-ds-dark-theme] table :is(th:first-child, td:first-child) {
    padding-left: 12px;
}

body[data-ds-dark-theme] table :is(th:last-child, td:last-child) {
    padding-right: 12px;
}

body[data-ds-dark-theme] table th {
    font-weight: 600;
    /* GitHub left-aligns headers; the browser default centres them */
    text-align: start;
}

sizes.full:
body[data-ds-dark-theme] :has(> table),
body[data-ds-dark-theme] .md-table-wide {
    width: 100%;
}

/* a short table still fills the column */
body[data-ds-dark-theme] table {
    min-width: 100%;
}

sizes.content:
/* Leave the width alone: the frontend already fills narrow tables and lets a
   table of four or more columns take its content width. */
body[data-ds-dark-theme] :has(> table),
body[data-ds-dark-theme] .md-table-wide {
    width: 100%;
}

body[data-ds-dark-theme] table {
    min-width: 0;
}

stripes.after:
body[data-ds-dark-theme] table tbody tr:nth-child(odd) {
    background: transparent;
}

body[data-ds-dark-theme] table tbody tr:nth-child(even) {
    background: #262a31;
}

stripes.first:
body[data-ds-dark-theme] table tbody tr:nth-child(odd) {
    background: #262a31;
}

body[data-ds-dark-theme] table tbody tr:nth-child(even) {
    background: transparent;
}

flows.wrap:
body[data-ds-dark-theme] table {
    width: 100%;
    table-layout: auto;
}

body[data-ds-dark-theme] table :is(th, td) {
    white-space: normal;
    overflow-wrap: anywhere;
}

flows.scroll:
body[data-ds-dark-theme] table {
    width: max-content;
}

body[data-ds-dark-theme] table :is(th, td) {
    white-space: nowrap;
}

body[data-ds-dark-theme] table :is(th, td):only-child {
    white-space: normal;
}
